// A plan is a sequence of element indices (0-based) and -1 (= reset).

static vector<int> expandBlocks(const vector<int>& bs, int b) {
    vector<int> p;
    for (int x : bs) {
        if (x < 0) { p.push_back(-1); continue; }
        for (int j = 0; j < b; j++) p.push_back(x * b + j);
    }
    return p;
}

