static vector<int> planTable() {
    for (auto& d : DESIGNS) {
        if (d.n != n || d.k != k) continue;
        vector<int> bs;
        const char* s = d.s;
        for (int i = 0; s[i] && s[i + 1]; i += 2) {
            int v = (s[i] - 48) * 64 + (s[i + 1] - 48);
            bs.push_back(v - 1);
        }
        return expandBlocks(bs, d.b);
    }
    return {};
}

static vector<int> planZigzag() {
    int b = max(1, k / 2);
    int m = n / b;
    vector<int> bs;
    if (m == 1) { bs.push_back(0); return expandBlocks(bs, b); }
    for (int i = 0; i < m / 2; i++) {
        if (i) bs.push_back(-1);
        bs.push_back(i);
        for (int s = 1; s < m / 2; s++) {
            bs.push_back((i + s) % m);
            bs.push_back((i - s + m) % m);
        }
        bs.push_back((i + m / 2) % m);
    }
    return expandBlocks(bs, b);
}

static vector<int> planCycle() {  // valid when n <= 2k
    vector<int> p;
    for (int i = 0; i < n; i++) p.push_back(i);
    for (int i = 0; i + 1 < k && i < n; i++) p.push_back(i);
    return p;
}

// all-distinct simulation: returns cost, or LLONG_MAX if coverage incomplete
static long long simulate(const vector<int>& plan) {
    vector<vector<char>> cov(n, vector<char>(n, 0));
    deque<int> mem;
    long long cost = 0;
    for (int x : plan) {
        if (x < 0) { mem.clear(); continue; }
        cost++;
        bool self = false;
        for (int y : mem) if (y == x) self = true;
        if (!self)
            for (int y : mem) cov[x][y] = cov[y][x] = 1;
        mem.push_back(x);
        if ((int)mem.size() > k) mem.pop_front();
    }
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if (!cov[i][j]) return LLONG_MAX;
    return cost;
}

// ---------------------------------------------------------------- executor
static vector<char> dead;
static vector<vector<char>> cv;     // verified distinct pairs
static vector<int> uncDeg;          // number of uncovered alive partners
static deque<int> mem;              // judge memory (indices)
static vector<int> segStamp;        // segment id when last queried
static int segId = 1;
static long long aliveCnt;
static long long uncoveredPairs;    // uncovered pairs among alive

static void doReset() {
    if (mem.empty()) { segId++; return; }
    printf("R\n");
    fflush(stdout);
    mem.clear();
    segId++;
}

static void markCovered(int x, int y) {
    if (x == y || cv[x][y]) return;
    cv[x][y] = cv[y][x] = 1;
    if (!dead[x] && !dead[y]) {
        uncDeg[x]--; uncDeg[y]--; uncoveredPairs--;
    }
}

static void kill(int x) {
    dead[x] = 1;
    aliveCnt--;
    for (int y = 0; y < n; y++)
        if (y != x && !dead[y] && !cv[x][y]) { uncDeg[y]--; uncoveredPairs--; }
    uncDeg[x] = 0;
}

// for a dead element w: alive elements w may equal (w equals at least one of them)
static vector<bitset<1024>> possEq;

static bool mightEq(int x, int y) {
    if (y == x) return true;
    if (!dead[y]) return !cv[x][y];
    const auto& B = possEq[y];
    for (int a = B._Find_first(); a < 1024; a = B._Find_next(a))
        if (a == x || !cv[x][a]) return true;
    return false;
}

// assuming a_x == a_y, is some alive element other than x surely equal to x?
static bool guaranteeOther(int x, int y) {
    if (y == x) return false;
    if (!dead[y]) return true;
    return !possEq[y][x];
}

// the single alive element known to equal y, or -1
static int twinRoot(int y) {
    if (!dead[y]) return y;
    if (possEq[y].count() == 1) return possEq[y]._Find_first();
    return -1;
}

// returns true on Y
static bool ask(int x) {
    printf("? %d\n", x + 1);
    fflush(stdout);
    char buf[16];
    if (scanf("%15s", buf) != 1) exit(0);
    if (buf[0] != 'Y' && buf[0] != 'N') exit(0);
    bool yes = buf[0] == 'Y';
    bool repeat = segStamp[x] == segId;
    if (!yes) {
        for (int y : mem) {
            markCovered(x, y);
            if (dead[y]) {
                int r = twinRoot(y);
                if (r >= 0) markCovered(x, r);
            }
        }
    } else {
        vector<int> cands;
        bool allGuaranteed = true;
        for (int y : mem) {
            if (y == x || !mightEq(x, y)) continue;
            cands.push_back(y);
            if (!guaranteeOther(x, y)) allGuaranteed = false;
        }
        bool doKill = (!cands.empty() && allGuaranteed) || !repeat;
        if (doKill) {
            bitset<1024> B;
            for (int c : cands) {
                if (!dead[c]) B[c] = 1;
                else B |= possEq[c];
            }
            B[x] = 0;
            kill(x);
            possEq[x] = B;
            // dead elements that may equal x may now equal what x may equal
            for (int w = 0; w < n; w++)
                if (w != x && dead[w] && possEq[w][x]) {
                    possEq[w][x] = 0;
                    possEq[w] |= B;
                    possEq[w][w] = 0;
                }
            if (B.count() == 1) {
                int r = twinRoot(x);
                if (r >= 0 && r != x)
                    for (int y = 0; y < n; y++)
                        if (y != r && cv[x][y]) markCovered(r, y);
            }
        }
    }
    segStamp[x] = segId;
    mem.push_back(x);
    if ((int)mem.size() > k) mem.pop_front();
    return yes;
}

static bool inMem(int x) {
    for (int y : mem) if (y == x) return true;
    return false;
}

static void executePlan(const vector<int>& plan) {
    int L = plan.size();
    for (int i = 0; i < L && uncoveredPairs > 0; i++) {
        int x = plan[i];
        if (x < 0) { doReset(); continue; }
        if (dead[x] || inMem(x) || uncDeg[x] == 0) continue;
        // useful? some uncovered alive partner in memory or upcoming in segment within k
        bool useful = false;
        for (int y : mem) if (!dead[y] && !cv[x][y]) { useful = true; break; }
        if (!useful) {
            int cnt = 0;
            for (int j = i + 1; j < L && cnt < k; j++) {
                int y = plan[j];
                if (y < 0) break;
                if (dead[y]) continue;
                cnt++;
                if (y != x && !cv[x][y]) { useful = true; break; }
            }
        }
        if (!useful) continue;
        ask(x);
    }
}

static void cleanup() {
    // segments without repeats; greedy on immediate gain plus future potential
    while (uncoveredPairs > 0) {
        doReset();
        vector<char> used(n, 0);
        int steps = 0;
        while (uncoveredPairs > 0) {
            vector<int> am;
            for (int y : mem) if (!dead[y]) am.push_back(y);
            // elements that will leave memory soon contribute less; keep it simple
            int best = -1;
            double bs = 0;
            for (int x = 0; x < n; x++) {
                if (dead[x] || used[x] || uncDeg[x] == 0) continue;
                int g = 0;
                for (int y : am) if (!cv[x][y]) g++;
                double sc = g + 0.5 * (uncDeg[x] - g);
                if (sc > bs + 1e-9) { bs = sc; best = x; }
            }
            if (best < 0) break;
            int g = 0;
            for (int y : am) if (!cv[best][y]) g++;
            if (g == 0 && steps > 0 && (int)mem.size() >= k) break;  // window exhausted
            used[best] = 1;
            ask(best);
            steps++;
        }
    }
}

int main() {
    if (scanf("%d %d", &n, &k) != 2) return 0;
    dead.assign(n, 0);
    cv.assign(n, vector<char>(n, 0));
    uncDeg.assign(n, n - 1);
    segStamp.assign(n, 0);
    possEq.assign(n, bitset<1024>());
    aliveCnt = n;
    uncoveredPairs = (long long)n * (n - 1) / 2;

    vector<vector<int>> cands;
    cands.push_back(planZigzag());
    if (n <= 2 * k) cands.push_back(planCycle());
    {
        auto p = planTable();
        if (!p.empty()) cands.push_back(p);
    }

    vector<int> best;
    long long bc = LLONG_MAX;
    for (auto& p : cands) {
        long long c = simulate(p);
        if (c < bc) { bc = c; best = p; }
    }
    if (n == 1) {
        printf("! 1\n");
        fflush(stdout);
        return 0;
    }
    executePlan(best);
    cleanup();
    printf("! %lld\n", aliveCnt);
    fflush(stdout);
    return 0;
}
